export function dailyRate(car,days){if(!Number.isInteger(days)||days<1)throw Error('Неверный срок');return days>=25?null:car.rates[days===1?0:days===2?1:days<=6?2:days<=14?3:4];}
export function priceFor(catalog,car,days,route='standard',equipment='none'){if(!catalog.routes[route]||!catalog.equipment[equipment])throw Error('Неизвестная опция');const rate=dailyRate(car,days),routeFee=car.routeFees?.[route]??catalog.routes[route].fee,equipmentFee=catalog.equipment[equipment].daily*days;return{rate,routeFee,equipmentFee,rent:rate===null?null:rate*days,total:rate===null?null:rate*days+routeFee+equipmentFee,deposit:car.deposit,negotiated:rate===null};}
